import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Frensense v2","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),n={name:"guide/index.md"};function s(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="frensense-v2" tabindex="-1">Frensense v2 <a class="header-anchor" href="#frensense-v2" aria-label="Permalink to &quot;Frensense v2&quot;">​</a></h1><p>Frensense is a <strong>compiler-mode static analysis engine</strong>. Instead of pattern matching on source text, it lowers every file into a lightweight IR and builds a full program graph:</p><ul><li>def-use chains and a call graph,</li><li>Steensgaard points-to with two-phase constraint solving,</li><li>heap modelling and a memory SSA backend,</li><li>an SVFG (Sparse Value-Flow Graph).</li></ul><p>Findings come from <strong>exact reachability queries</strong> on this graph, and every report includes the concrete source-to-sink path with file positions, not a confidence score.</p><h2 id="what-it-detects-out-of-the-box" tabindex="-1">What it detects out of the box <a class="header-anchor" href="#what-it-detects-out-of-the-box" aria-label="Permalink to &quot;What it detects out of the box&quot;">​</a></h2><p>Command injection, SQL/NoSQL injection, SSRF, path traversal, IDOR, weak cryptography, XSS, session-trust and guard-bypass violations, use-after-free / double-free, and out-of-bounds accesses.</p><p><code>.frc</code> knowledge bundles extend and sharpen detection, see <a href="/corpus/">Corpus &amp; bundles</a>.</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>v2 is a <strong>preview</strong> (<code>0.7.1-preview.1</code>). The knowledge-bundle format and CLI surface may still change before the stable release.</p><blockquote><p><strong>Coming from v1?</strong> The legacy v1 documentation is preserved at <a href="/v1/">/v1/</a> and its sources live in the <a href="https://github.com/Friehub/Frensense" target="_blank" rel="noreferrer">Friehub/Frensense</a> repository. v2 is a ground-up rebuild of the engine; see the <a href="/architecture/">architecture overview</a> for what changed.</p></blockquote>',10)])])}const f=t(n,[["render",s]]);export{p as __pageData,f as default};
